'use strict';
const BASE_PATH = '/energy-md';
function localPath(path) { return path === BASE_PATH ? '/' : path.startsWith(BASE_PATH + '/') ? path.slice(BASE_PATH.length) : path; }

const UI_LANG = window.ENERGY_LANG || 'ru';
let DATASETS;
let DATA, saved = new Set(), filtered = [];
const searchKey = value => String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase();
const $ = (q, root = document) => root.querySelector(q);
const $$ = (q, root = document) => [...root.querySelectorAll(q)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = (n, digits = 0) => Number(n).toLocaleString(UI_LANG==='ro'?'ro-RO':'ru-RU', {maximumFractionDigits:digits,minimumFractionDigits:digits});
const money = n => num(n / 1000000, 2) + ' млн MDL';
const priority = {A:'Приоритетная проверка',B:'Уточнить данные',S:'Крупные группы'};
const getCompany = id => DATA.companies.find(c => c.id === id);
const getSector = name => DATA.sectors.find(s => s.name === name);
const route = localPath(location.pathname).replace(/\/+$/, '') || '/';
const params = new URLSearchParams(location.search);
const sectorUrl = s => '/energy-md/sector/' + s.id + '/';
const companyUrl = c => '/energy-md/company/' + c.id + '/';
const links = raw => [...new Set(String(raw ?? '').match(/https?:\/\/[^\s<>";]+/g) || [])].map(s=>s.replace(/[),]+$/,''));
const sourceLinks = raw => `<div class="source-links">${links(raw).map(u => {let label; try{label=new URL(u).hostname.replace(/^www\./,'');}catch{return '';}return `<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;}).join('')}</div>`;
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3000);}
async function copyText(value){try{await navigator.clipboard.writeText(value);toast('Скопировано. Можно вставить в поиск или чат.');return true;}catch{const t=document.createElement('textarea');t.value=value;t.style.position='fixed';t.style.top='-9999px';document.body.append(t);t.select();let ok=false;try{ok=document.execCommand('copy');}catch{}t.remove();toast(ok?'Текст скопирован.':'Не удалось скопировать. Выделите текст в поле вручную.');return ok;}}
function loadSaved(){try{const a=JSON.parse(localStorage.getItem('energy-md-saved')||'[]');if(Array.isArray(a))saved=new Set(a.filter(id=>DATA.companies.some(c=>c.id===id)));}catch{saved=new Set();}}
function saveButton(c){return `<button class="save ${saved.has(c.id)?'saved':''}" data-save="${c.id}" aria-label="${saved.has(c.id)?'Убрать из избранного':'В избранное'}: ${esc(c.name)}" aria-pressed="${saved.has(c.id)}" title="Избранное на этом устройстве">${saved.has(c.id)?'★':'☆'}</button>`;}
function pageHead(title,desc='',parent=''){return `<div class="page-head"><div class="breadcrumb"><a href="/energy-md/">Главная</a><span>/</span>${parent?parent+'<span>/</span>':''}<span>${esc(title)}</span></div><h1>${esc(title)}</h1>${desc?`<p>${desc}</p>`:''}</div>`;}
function notice(){return '<div class="note-strip"><strong>Порог отбора — от 30 000 MDL в месяц.</strong> Расходы компаний пока не подтверждены счетами. Оборот, оборудование и процессы — основания для проверки, а не измеренное потребление.</div>';}
function companyCard(c,rank=false){return `<article class="company-card"><div class="card-top"><div>${rank?`<span class="wave-rank">${String(c.wave.rank).padStart(2,'0')} / </span>`:''}<span class="tag ${c.priority}" title="${priority[c.priority]}">${c.priority} · ${priority[c.priority]}</span></div>${saveButton(c)}</div><h3><a href="${companyUrl(c)}">${esc(c.name)}</a></h3><a class="sector-label" href="${sectorUrl(getSector(c.sector))}">${esc(c.sector)} ↗</a><p class="fact">${esc(c.facts)}</p><div class="card-meta">${dayBadge(c)}${c.finance?`<span class="tag">${money(c.finance.revenue)} · ${c.finance.year}</span>`:'<span class="tag">Выручка не указана</span>'}${c.wave&&!rank?'<span class="tag orange">Исходная волна</span>':''}</div><div class="card-bottom"><a href="${companyUrl(c)}">Разобрать компанию ↗</a><button class="copy-small" data-copy-question="${c.id}" title="Копировать вопрос для квалификации">Копировать вопрос</button></div></article>`;}
function sectorTile(s,i=0){return `<a class="sector-tile" href="${sectorUrl(s)}"><div class="sector-top"><span>${String(i+1).padStart(2,'0')} / НАПРАВЛЕНИЕ</span><span>↗</span></div><h3>${esc(s.name)}</h3><p>${s.count} ${s.count===1?'карточка':s.count<5?'карточки':'карточек'} в исследовании</p><div class="track"><span style="width:${s.count*10}%"></span></div></a>`;}
function home(){const tops=[...DATA.sectors].sort((a,b)=>b.count-a.count).slice(0,6);return `<section class="hero"><div><div class="eyebrow">Республика Молдова · исследование 17.10.2026</div><h1>Найти бизнес,<br>которому важна<br><em>цена энергии.</em></h1><p class="hero-description">Ищем предприятия с дневной электрической нагрузкой. Производство, опубликованные графики и реальные месячные объёмы помогают выбрать следующего клиента.</p><div class="actions"><a class="button" href="/energy-md/catalog/">Подобрать компании <span>↗</span></a><a class="button secondary" href="/energy-md/research/">Собрать запрос <span>+</span></a></div><p class="small-note">Для предприятий и организаций. Основной приоритет — работа днём.</p></div><div class="hero-board"><div class="board-grid"></div><div class="board-top"><span><i class="live-dot"></i> КРИТЕРИЙ ОТБОРА</span><span>MD / 2026</span></div><div class="threshold"><div class="number">30 000<span style="font-size:.4em">+</span></div><div class="unit"><span>MDL за электричество в месяц</span><span>НЕ МОЩНОСТЬ В кВт</span></div></div><p class="board-caption">Ищем основания для проверки:<br>дневная работа производства,<br>оборудование и масштаб.</p><div class="load-bars" aria-hidden="true">${[24,40,34,58,43,65,52,75,61,88,74,100,85,92,78,95].map(v=>`<i style="height:${v}%"></i>`).join('')}</div><div class="board-foot"><span>СХЕМА · НЕ ДАННЫЕ ПОТРЕБЛЕНИЯ</span><span>↗</span></div></div></section><section class="stats" aria-label="Объём базы"><div class="stat"><strong>${DATA.companies.length}</strong><span>компаний<br>и групп</span></div><div class="stat"><strong>${DATA.sectors.length}</strong><span>отраслевых<br>направлений</span></div><div class="stat"><strong>25</strong><span>записей<br>с выручкой</span></div><div class="stat"><strong>${dayCandidates().length}</strong><span>опубликованных<br>дневных графиков</span></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">01 / Карта поиска</div><h2>Отрасли с основаниями<br>для проверки нагрузки</h2></div><a class="text-link" href="/energy-md/sectors/">Все ${DATA.sectors.length} направлений ↗</a></div><div class="sector-grid">${tops.map(sectorTile).join('')}</div></section><section class="dark-section"><div><div class="eyebrow">02 / От сигнала к решению</div><h2>Оборот — повод<br>задать вопрос.<br>Дневной профиль —<br>основа отбора.</h2><p>В базе пока нет подтверждённых расходов выше порога. Каждый этап помогает уточнить, подходит ли компания для сравнения условий поставки.</p><a class="button secondary" style="color:white;border-color:#ffffff55" href="/energy-md/method/">Как устроен отбор ↗</a></div><div class="steps"><div class="step"><span>01</span><div><h3>Найти производственный сигнал</h3><p>Холодильные камеры, станки, экструзия, насосы, несколько смен.</p></div></div><div class="step"><span>02</span><div><h3>Проверить масштаб и площадку</h3><p>Оборот, действующее оборудование, адрес объекта и юридический плательщик.</p></div></div><div class="step"><span>03</span><div><h3>Подтвердить закупки из сети</h3><p>Фактические счета, сезонность и остаток после собственной генерации.</p></div></div><div class="step"><span>04</span><div><h3>Сравнить условия поставки</h3><p>Одинаковый объём, состав цены и условия договора. Экономия требует расчёта.</p></div></div></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">03 / Начать предметно</div><h2>Дневной приоритет</h2></div><a class="text-link" href="/energy-md/wave/">${dayCandidates().length} дневных графиков ↗</a></div><div class="company-grid">${dayCandidates().slice(0,3).map(c=>companyCard(c)).join('')}</div><div class="callout"><div><h3>Следующий вопрос уже рядом.</h3><p>Соберите запрос по компании или отрасли, уточните задачу и скопируйте для дальнейшего поиска.</p></div><a class="button" href="/energy-md/research/">Открыть конструктор ↗</a></div></section>`;}
function catalog(){return pageHead('Компании, с которых стоит начать',`${DATA.companies.length} карточек. Основной приоритет — дневные закупки из сети от 30 000 MDL/мес. Фильтр показывает степень подтверждения графика, а не измеренную дневную долю.`)+`<div class="content"><div class="filters"><div class="field"><label for="q">Поиск по базе</label><input type="search" id="q" placeholder="Компания, город, процесс, IDNO…" autocomplete="off"></div><div class="field"><label for="sector-filter">Направление</label><select id="sector-filter"><option value="">Все ${DATA.sectors.length} направлений</option>${DATA.sectors.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label for="priority-filter">Очередь</label><select id="priority-filter"><option value="">Все очереди</option><option value="A">A · приоритет</option><option value="B">B · уточнение</option><option value="S">S · группы</option></select></div><div class="field"><label for="day-filter">Дневной профиль</label><select id="day-filter"><option value="">Все статусы</option><option value="signal">Есть опубликованный график</option>${Object.entries(DATA.dayLabels).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></div><div class="field"><label for="sort-filter">Порядок</label><select id="sort-filter"><option value="day">Сначала дневные сигналы</option><option value="id">По базе</option><option value="name">По названию</option><option value="revenue">По выручке ↓</option><option value="wave">Исходная волна</option></select></div><div class="filter-bottom"><label class="check"><input type="checkbox" id="finance-only">Есть данные о выручке</label><label class="check"><input type="checkbox" id="wave-only">Исходная волна</label><label class="check"><input type="checkbox" id="saved-only">Избранное</label><button class="reset" id="reset-filters">Сбросить фильтры</button></div></div><div class="legend"><span>A — приоритетная квалификация</span><span>B — уточнить масштаб / данные</span><span>S — отдельный подход к группе</span></div><div class="results-bar"><span id="result-count" aria-live="polite"></span><button class="button secondary small" id="export-csv">Скачать подборку CSV ↓</button></div><div id="company-results" class="company-grid"></div>${notice()}<p class="small-note">Звёздочка сохраняет избранное в этом браузере. Выручка относится к разным годам и не равна затратам на электричество. Экспорт содержит текущую подборку с источниками.</p></div>`;}
function initCatalog(){const controls=['q','sector-filter','priority-filter','day-filter','sort-filter','finance-only','wave-only','saved-only'];$('#q').value=params.get('q')||'';$('#sector-filter').value=params.get('sector')||'';$('#priority-filter').value=params.get('priority')||'';$('#day-filter').value=params.get('day')||'';$('#sort-filter').value=params.get('sort')||'day';$('#wave-only').checked=params.get('wave')==='1';$('#finance-only').checked=params.get('finance')==='1';$('#saved-only').checked=params.get('saved')==='1';controls.forEach(id=>$('#'+id).addEventListener(id==='q'?'input':'change',filterCatalog));$('#reset-filters').addEventListener('click',()=>{controls.forEach(id=>{const e=$('#'+id);if(e.type==='checkbox')e.checked=false;else e.value=id==='sort-filter'?'day':'';});filterCatalog();});$('#export-csv').addEventListener('click',exportCSV);filterCatalog();}
function filterCatalog(){const q=searchKey($('#q').value.trim());const sector=DATA.sectors.find(s=>s.id===$('#sector-filter').value)?.name;const p=$('#priority-filter').value;filtered=DATA.companies.filter(c=>(!q||searchKey([c.id,c.name,c.sector,c.location,c.facts,c.inference,c.finance?.idno,c.idno,c.day.hours,c.day.evidence,...Object.values((DATASETS?.[UI_LANG==='ro'?'ru':'ro']?.companies.find(x=>x.id===c.id))||{})].join(' ')).includes(q))&&(!$('#day-filter').value||($('#day-filter').value==='signal'?['factory','shift','general'].includes(c.day.kind):c.day.kind===$('#day-filter').value))&&(!sector||c.sector===sector)&&(!p||c.priority===p)&&(!$('#finance-only').checked||c.finance)&&(!$('#wave-only').checked||c.wave)&&(!$('#saved-only').checked||saved.has(c.id)));const sort=$('#sort-filter').value;filtered.sort(sort==='day'?(a,b)=>dayOrder[a.day.kind]-dayOrder[b.day.kind]:sort==='name'?(a,b)=>a.name.localeCompare(b.name,UI_LANG):sort==='revenue'?(a,b)=>(b.finance?.revenue||-1)-(a.finance?.revenue||-1):sort==='wave'?(a,b)=>(a.wave?.rank||999)-(b.wave?.rank||999):(a,b)=>a.id.localeCompare(b.id));$('#result-count').innerHTML=`Найдено <strong>${filtered.length}</strong> из ${DATA.companies.length} карточек`;$('#export-csv').disabled=!filtered.length;$('#company-results').innerHTML=filtered.length?filtered.map(c=>companyCard(c)).join(''):'<div class="empty"><h3>В этой подборке пока нет компаний</h3><p>Уберите часть фильтров или измените поисковую фразу.</p><button class="button secondary" data-reset>Сбросить фильтры</button></div>';const pms=new URLSearchParams({lang:UI_LANG});if(q)pms.set('q',$('#q').value.trim());if(sector)pms.set('sector',$('#sector-filter').value);if(p)pms.set('priority',p);if($('#day-filter').value)pms.set('day',$('#day-filter').value);if(sort!=='day')pms.set('sort',sort);if($('#finance-only').checked)pms.set('finance','1');if($('#wave-only').checked)pms.set('wave','1');if($('#saved-only').checked)pms.set('saved','1');history.replaceState(null,'',location.pathname+(pms.size?'?'+pms:''));}
function exportCSV(){const rows=[['ID','Компания','Направление','Очередь','Адрес / география','Опубликованные сведения','Аналитический вывод','Вопрос для проверки','Телефон','Email / форма','Назначение контакта','Кого запросить','Выручка MDL','Год','IDNO','Источник деятельности','Источник контакта','Источник финансов','Расход электроэнергии','Дневной статус','Опубликованные часы','Основание графика','Источник графика'],...filtered.map(c=>[c.id,c.name,c.sector,c.priority,c.location,c.facts,c.inference,c.question,c.contact.phone,c.contact.email,c.contact.quality,c.contact.person,c.finance?.revenue??'',c.finance?.year??'',c.idno||c.finance?.idno||'',c.sources,c.contact.sources,c.finance?.sources??'','Не подтверждён',c.day.label,c.day.hours,c.day.evidence,c.day.sources])];const cell=v=>{let s=String(v??'');if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Energy-Selection.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Подборка выгружена: '+filtered.length+' карточек.');}
function sectors(){return pageHead(`${DATA.sectors.length} направлений. Один критерий.`,'Расширяем поиск через процессы, которые могут создавать регулярную электрическую нагрузку. Количество карточек отражает эту выборку, а не размер отрасли.')+`<div class="content"><div class="sector-grid">${DATA.sectors.map(sectorTile).join('')}</div>${notice()}</div>`;}
function sectorPage(s){const items=DATA.companies.filter(c=>c.sector===s.name);return pageHead(s.name,'Предприятия этого направления, опубликованные сведения и вопросы для дальнейшего исследования.','<a href="/energy-md/sectors/">Направления</a>')+`<div class="content"><div class="sector-intro"><div><div class="panel"><span class="label inference">ВЫВОД · ЛОГИКА ОТБОРА</span><h2>Проверяем процесс и его масштаб</h2><p>${esc(items[0].inference)}</p><p class="small-note">Это основание из карточки ${esc(items[0].name)}. Для остальных предприятий нужны их собственные данные о загрузке и оборудовании.</p><div class="actions"><a class="button" href="/energy-md/research/?sector=${s.id}">Запрос по направлению ↗</a><a class="button secondary" href="/energy-md/catalog/?sector=${s.id}">Фильтровать компании</a></div></div></div><section class="sector-stat" aria-labelledby="sector-summary-title"><h2 id="sector-summary-title" class="sector-stat-title">В ЭТОЙ ВЫБОРКЕ</h2><div class="sector-stat-total"><strong>${items.length}</strong><p>карточек компаний и групп</p></div><dl class="data-list"><div><dt>Приоритет A</dt><dd>${items.filter(c=>c.priority==='A').length}</dd></div><div><dt>Исходная волна</dt><dd>${items.filter(c=>c.wave).length}</dd></div><div><dt>С опубликованной выручкой</dt><dd>${items.filter(c=>c.finance).length}</dd></div></dl></section></div><div class="company-grid">${items.map(c=>companyCard(c)).join('')}</div>${notice()}</div>`;}
function wave(){return dayWave();}
function companyPage(c){const f=c.finance;const con=c.contact;return pageHead(c.name,esc(c.location),'<a href="/energy-md/catalog/">Компании</a>')+`<div class="content"><div class="subtitle-line"><span class="tag">${c.id}</span><span class="tag ${c.priority}">${c.priority} · ${priority[c.priority]}</span><a class="tag" href="${sectorUrl(getSector(c.sector))}">${esc(c.sector)} ↗</a>${c.wave?`<a class="tag orange" href="/energy-md/catalog/?wave=1&amp;sort=wave">Исходная волна · № ${c.wave.rank}</a>`:''}${saveButton(c)}</div><div class="detail-grid"><div><section class="panel"><div class="evidence-block"><span class="label">ОПУБЛИКОВАНО · ДЕЯТЕЛЬНОСТЬ</span><h2>Деятельность и масштаб</h2><p>${esc(c.facts)}</p>${sourceLinks(c.sources)}<p class="small-note" style="margin-top:12px">${esc(c.reviewStatus)}. Дневной профиль имеет отдельное основание и источник ниже.</p></div><div class="evidence-block"><span class="label inference">ВЫВОД · ПРИЧИНА ВКЛЮЧЕНИЯ</span><p>${esc(c.inference)}</p></div><div class="evidence-block"><span class="label unchecked">НЕ ПРОВЕРЕНО · СЛЕДУЮЩИЙ ВОПРОС</span><p>${esc(c.question)}</p><button class="button secondary small" data-copy-question="${c.id}">Копировать вопрос ⧉</button></div></section>${c.wave?`<section class="panel"><span class="label inference">ИСХОДНАЯ ВОЛНА · № ${c.wave.rank}</span><h3>С чего начать разговор</h3><p>${esc(c.wave.question)}</p><button class="copy-small" data-copy-wave="${c.id}">Копировать первый вопрос ⧉</button></section>`:''}<section class="panel"><h2>Продолжить исследование</h2><p>Проверить актуальность компании, найти производственную площадку, уточнить финансовые данные или составить вопросы ответственному за электричество.</p><a class="button" href="/energy-md/research/?company=${c.id}">Собрать запрос по компании ↗</a></section></div><aside>${dayPanel(c)}<section class="panel"><span class="label">ДЕЛОВОЙ КОНТАКТ</span><h2>Выход на ответственное лицо</h2><p class="contact-number">${esc(con.phone)}</p><p class="contact-email">${esc(con.email)}</p><p>${esc(con.quality)}</p><div class="contact-route"><strong>Кого запросить</strong><br>${esc(con.person)}</div><button class="button secondary small" data-copy-contact="${c.id}">Копировать контакты ⧉</button>${sourceLinks(con.sources)}<p class="small-note" style="margin-top:15px">Контакт не проверялся звонком. Переписка не отправлялась.</p></section><section class="panel"><span class="label">МАСШТАБ БИЗНЕСА</span><h2>Выручка и штат</h2>${f?`<dl class="data-list"><div><dt>Выручка, ${f.year}</dt><dd class="big">${money(f.revenue)}</dd></div><div><dt>Сотрудников</dt><dd>${esc(f.employees)}</dd></div><div><dt>IDNO</dt><dd>${esc(f.idno)}</dd></div><div><dt>360 тыс. / выручка</dt><dd>${num(360000/f.revenue*100,3)}%</dd></div></dl><p class="small-note" style="margin-top:17px">${esc(f.sourceType)}. ${esc(f.limitation)}</p>${sourceLinks(f.sources)}<div class="note-strip">Доля годового порога в выручке — арифметический ориентир. Фактическая доля затрат на электричество неизвестна.</div>`:'<p>В этих документах нет финансовой записи по компании. Это не означает отсутствие выручки.</p><a class="text-link" href="/energy-md/research/?company='+c.id+'&task=finance">Подготовить финансовый поиск ↗</a>'}</section></aside></div>${notice()}</div>`;}
const tasks=[{id:'full',title:'Полный разбор компании',desc:'Статус, площадки, производство, масштаб, источники и неизвестные данные.'},{id:'expand',title:'Расширить список компаний',desc:'Найти похожие предприятия и организации за пределами текущей базы.'},{id:'finance',title:'Проверить выручку и юрлицо',desc:'Год отчётности, IDNO, первичный отчёт, штат и охват показателей.'},{id:'contact',title:'Найти ответственного',desc:'Публичный рабочий контакт и маршрут к закупкам или главному инженеру.'},{id:'load',title:'Уточнить электрическую нагрузку',desc:'Процессы, смены, сезонность, собственная генерация и сетевые покупки.'},{id:'interview',title:'Подготовить вопросы для разговора',desc:'Короткая квалификация перед запросом счетов и договора.'}];
function research(){return pageHead('Хороший поиск начинается с вопроса.','Выберите компанию или направление, задачу и язык поиска. Получите редактируемый запрос, который можно скопировать в поисковую систему или ИИ-ассистент.')+`<div class="content"><div class="research-grid"><section class="panel"><span class="label">01 / НАСТРОЙТЕ ЗАДАЧУ</span><div class="research-options"><div class="field"><label for="research-company">Компания</label><select id="research-company"><option value="">Без конкретной компании</option>${[...DATA.companies].sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="research-sector">Направление</label><select id="research-sector"><option value="">Все направления</option>${DATA.sectors.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label for="research-task">Что нужно выяснить</label><select id="research-task">${tasks.map(t=>`<option value="${t.id}">${t.title}</option>`).join('')}</select></div><div class="field"><label for="research-lang">Язык запроса и ответа</label><select id="research-lang"><option value="ru">Русский</option><option value="ro">Румынский</option><option value="both">Русский и румынский</option></select></div><div class="field"><label for="research-sources">Язык источников для поиска</label><select id="research-sources"><option value="both">Русский и румынский</option><option value="ro">Румынский</option><option value="ru">Русский</option><option value="all">Русский, румынский и английский</option></select></div><div class="field"><label for="research-extra">Дополнительное условие</label><input id="research-extra" placeholder="Например: Бельцы, холодильные склады" maxlength="500"></div><button class="button" id="build-prompt">Сформировать запрос ↗</button></div><p class="small-note" style="margin-top:18px">Запрос обновляется при выборе условий. Ручные правки сохраняются до нажатия «Сформировать запрос». Данные не отправляются.</p></section><section class="panel"><div class="prompt-head"><div><span class="label">02 / СКОПИРУЙТЕ И ПРОДОЛЖИТЕ</span><h2>Ваш запрос</h2></div><button class="button orange small" id="copy-prompt">Копировать ⧉</button></div><div class="field"><label for="prompt-text" class="small-note">Текст можно редактировать перед копированием</label><textarea id="prompt-text" spellcheck="false"></textarea></div><p id="prompt-status" class="small-note" role="status" aria-live="polite"></p><div id="search-shortcuts" class="search-links"></div><p class="small-note">Ссылки открывают поиск в новой вкладке. Результаты поиска не добавляются в базу автоматически.</p></section></div><div class="subsection"><div class="section-head"><h2>Шесть исследовательских задач</h2><p>Шаблоны учитывают выбранную компанию или отрасль.</p></div><div class="template-grid">${tasks.map((t,i)=>`<button class="template" data-task="${t.id}"><span>0${i+1} / ШАБЛОН</span><strong>${t.title}</strong><p>${t.desc}</p><em>Применить к запросу ↗</em></button>`).join('')}</div></div></div>`;}
function makePrompt(){
  const lang=$('#research-lang').value||UI_LANG;
  const ru=()=>composePromptRU(DATASETS.ru),ro=()=>composePromptRO(DATASETS.ro);
  return lang==='both'?ru()+'\n\n──────── ROMÂNĂ ────────\n\n'+ro():lang==='ro'?ro():ru();
}
function buildPrompt(){
  $('#prompt-text').value=makePrompt();
  $('#prompt-text').dataset.generated=$('#prompt-text').value;
  $('#prompt-text').lang=$('#research-lang').value==='both'?UI_LANG:$('#research-lang').value;
  $('#prompt-status').textContent='Запрос готов. Можно редактировать и копировать.';
  buildSearchLinks();
}
function buildSearchLinks(){
  const company=getCompany($('#research-company').value),id=$('#research-sector').value;
  const languages=$('#research-sources').value==='all'?['ru','ro','en']:$('#research-sources').value==='both'?['ru','ro']:[$('#research-sources').value];
  const terms={ru:['предприятия Молдовы','Молдова производство фабрика контакты','Молдова выручка финансовый отчёт'],ro:['întreprinderi Moldova','Moldova producere fabrică contacte','Moldova venituri raport financiar'],en:['Moldova companies','Moldova manufacturing factory contacts','Moldova revenue financial report']};
  $('#search-shortcuts').innerHTML=languages.map(lang=>{
    const term=company?.name||DATASETS[lang==='en'?'ro':lang].sectors.find(s=>s.id===id)?.name||terms[lang][0];
    const query=term+' '+terms[lang][1],financial=(company?.idno||company?.finance?.idno||term)+' '+terms[lang][2];
    return `<a target="_blank" rel="noopener noreferrer" href="https://www.google.com/search?q=${encodeURIComponent(query)}">Поиск деятельности · ${lang.toUpperCase()} ↗</a><a target="_blank" rel="noopener noreferrer" href="https://www.google.com/search?q=${encodeURIComponent(financial)}">Поиск финансов · ${lang.toUpperCase()} ↗</a>`;
  }).join('');
}
function initResearch(){
  $('#research-company').value=params.get('company')||'';
  const c=getCompany($('#research-company').value);
  $('#research-sector').value=c?getSector(c.sector).id:(params.get('sector')||'');
  $('#research-task').value=params.get('task')||(c?'full':'expand');
  if(!$('#research-task').value)$('#research-task').value='full';
  $('#research-lang').value=UI_LANG;
  $('#research-sector').disabled=!!c;
  const change=()=>{
    const selected=getCompany($('#research-company').value);
    $('#research-sector').disabled=!!selected;
    if(selected)$('#research-sector').value=getSector(selected.sector).id;
    const edited=$('#prompt-text').value!==$('#prompt-text').dataset.generated;
    if(!edited)buildPrompt();
    else {$('#prompt-status').textContent='Настройки изменены. Нажмите «Сформировать запрос», чтобы заменить отредактированный текст.';buildSearchLinks();}
  };
  ['research-company','research-sector','research-task','research-lang','research-sources'].forEach(id=>$('#'+id).addEventListener('change',change));
  $('#research-extra').addEventListener('input',change);
  $('#build-prompt').addEventListener('click',()=>{buildPrompt();toast('Запрос сформирован с выбранными условиями.');});
  $('#copy-prompt').addEventListener('click',()=>copyText($('#prompt-text').value));
  buildPrompt();
}

function method(){return pageHead('От признаков — к подтверждённому клиенту.','Методика помогает расширять поиск и сохранять точность. Включение в каталог означает основание для проверки, а не установленный размер счёта.')+`<div class="content"><div class="method-grid"><section class="panel"><div class="number">01</div><span class="label">ОПУБЛИКОВАНО</span><h3>Что сообщает источник</h3><p>Процесс, оборудование, размеры фабрики, число камер, оборот или штат. Ссылка и год сохраняются вместе с фактом. Данные агрегатора требуют сверки.</p></section><section class="panel"><div class="number">02</div><span class="label inference">ВЫВОД</span><h3>Почему стоит проверить</h3><p>Сочетание процесса и масштаба позволяет выбрать кандидата. Приоритет A, B или S определяет порядок работы и не измеряет потребление.</p></section><section class="panel"><div class="number">03</div><span class="label unchecked">НЕ ПРОВЕРЕНО</span><h3>Что должен подтвердить клиент</h3><p>Помесячные счета, закупки из сети, поставщик, договор и готовность перейти. Без этих данных нельзя считать экономию или обещать её размер.</p></section></div><div class="subsection detail-grid"><section class="panel"><span class="label">ДЕНЕЖНЫЙ КРИТЕРИЙ</span><h2>30 000 × 12 = 360 000 MDL</h2><p>Годовой эквивалент нижнего порога. Деление 360 000 MDL на годовую выручку показывает, какой доли оборота достаточно для достижения порога.</p><div class="note-strip">Это не расчёт фактических затрат компании. Для сезонного бизнеса средняя годовая сумма не заменяет проверку минимального и обычного месяца.</div><p>Порог применяется к юридическому плательщику и согласованному набору объектов. Суммы с НДС, без НДС, кВт·ч и периоды записываются отдельно.</p></section><section class="panel"><h2>Что меняет приоритет</h2><p><strong>Усиливает основание:</strong> подтверждённый график производственной дневной смены, серийные электрические процессы и действующая площадка.</p><p><strong>Требует уточнения:</strong> ночные смены, круглосуточный холод, сезонность, газовые печи, аренда, торговая выручка и собственная генерация.</p><a class="text-link" href="/energy-md/sources/#reserve">Посмотреть отложенные записи ↗</a></section></div><div class="subsection"><h2>Пять шагов квалификации</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Таблица; прокрутите по горизонтали"><table class="financial-table"><thead><tr><th>ШАГ</th><th>ЧТО УСТАНОВИТЬ</th><th>РЕЗУЛЬТАТ</th></tr></thead><tbody><tr><td>01 · Порог</td><td>Обычный, минимальный и максимальный месячный счёт; НДС</td><td>Закупки от 30 000 MDL / месяц</td></tr><tr><td>02 · Объект</td><td>Юрлицо, IDNO, площадка, счётчик, аренда</td><td>Определён предмет предложения</td></tr><tr><td>03 · Профиль</td><td>кВт·ч по месяцам, смены, ночь, выходные, генерация</td><td>Понятны сетевые покупки</td></tr><tr><td>04 · Договор</td><td>Поставщик, состав цены, сроки и условия изменения</td><td>Известен порядок перехода</td></tr><tr><td>05 · Расчёт</td><td>Сопоставимый объём, платежи и условия поставки</td><td>Экономия подтверждается расчётом</td></tr></tbody></table></div><div class="callout"><div><h3>Готовые вопросы для следующего шага</h3><p>Выберите компанию, чтобы учесть её процессы в сценарии разговора.</p></div><a class="button" href="/energy-md/research/?task=interview">Собрать вопросы ↗</a></div></div></div>`;}
function sources(){const finances=DATA.companies.filter(c=>c.finance).sort((a,b)=>b.finance.revenue-a.finance.revenue);return pageHead('Источники, документы и границы данных.','Исходные документы сохранены. Дополнительно исследованы производственные сайты, вакансии, UPM, официальный реестр ASP и месячные данные CNED. Дата проверки — 17.10.2026; даты выгрузок указаны отдельно.')+`<div class="content"><div class="document-row"><div class="file-icon">XLSX</div><div><h3>Energy-Day.xlsx</h3><p>${DATA.companies.length} карточек · дневной профиль · реестр ASP · потребление CNED</p></div><a class="button" href="/energy-md/files/Energy-Day.xlsx" download>Расширенная база ↓</a></div><div class="document-row"><div class="file-icon">XLSX</div><div><h3>Energy-Industry.xlsx</h3><p>6 листов · 80 кандидатов · контакты · обороты · первая волна · резерв</p></div><a class="button secondary" href="/energy-md/files/Energy-Industry.xlsx" download>Скачать Excel ↓</a></div><div class="document-row"><div class="file-icon" style="background:var(--accent);color:white">PDF</div><div><h3>Energy-Analysis.pdf</h3><p>9 страниц · выводы исследования · логика отбора · ограничения</p></div><a class="button secondary" href="/energy-md/files/Energy-Analysis.pdf" download>Скачать отчёт ↓</a></div><div class="note-strip"><strong>Что подтверждено документами:</strong> наличие 80 карточек, 26 направлений, 25 финансовых записей и 20 кандидатов первой волны. <strong>Что не установлено:</strong> фактические расходы выше порога, текущие поставщики, готовность сменить поставщика и возможная экономия.</div><section class="subsection"><div class="section-head"><h2>Финансовые источники</h2><p>4 записи APP и 21 запись из агрегаторов. Выручка относится к конкретному году и юрлицу.</p></div><div class="table-wrap" tabindex="0" role="region" aria-label="Таблица; прокрутите по горизонтали"><table class="financial-table"><thead><tr><th>КОМПАНИЯ</th><th>ГОД</th><th>ВЫРУЧКА, МЛН MDL</th><th>ИСТОЧНИК</th></tr></thead><tbody>${finances.map(c=>`<tr><td><a href="${companyUrl(c)}">${esc(c.name)} ↗</a></td><td>${c.finance.year}</td><td>${num(c.finance.revenue/1000000,2)}</td><td>${sourceLinks(c.finance.sources)}</td></tr>`).join('')}</tbody></table></div><p class="small-note" style="margin-top:15px">Sandriliona: 2024 год. Purcari: округлённая выручка местного юрлица. Barza Albă: пересчёт из тысяч MDL. Полные оговорки доступны в карточках компаний.</p></section><section class="subsection" id="reserve"><div class="section-head"><h2>9 записей для дополнительной проверки</h2><p>Резерв не входит в основной каталог. Причины и следующие действия сохранены из Excel.</p></div><div class="reserve-grid">${DATA.reserve.map(r=>`<details><summary>${esc(r.name)} <span class="muted">/ ${esc(r.sector)}</span></summary><p><strong>Опубликовано:</strong> ${esc(r.facts)}</p><p><strong>Почему отложено:</strong> ${esc(r.reason)}</p><p><strong>Следующее действие:</strong> ${esc(r.action)}</p>${sourceLinks(r.sources)}<button class="copy-small" data-copy-reserve="${r.id}">Копировать задачу ⧉</button></details>`).join('')}</div></section></div>`;}
function bindGlobal(){document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.save;if(id){const old=new Set(saved);saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('energy-md-saved',JSON.stringify([...saved]));}catch{saved=old;toast('Браузер не разрешил сохранить избранное.');return;}if(route==='/catalog')filterCatalog();else $$(`[data-save="${id}"]`).forEach(el=>{el.outerHTML=saveButton(getCompany(id));});toast(saved.has(id)?'Компания добавлена в избранное этого браузера.':'Компания убрана из избранного.');}if(b.dataset.copyQuestion){const c=getCompany(b.dataset.copyQuestion);await copyText(c.name+'\n'+c.question);}if(b.dataset.copyWave){const c=getCompany(b.dataset.copyWave);await copyText(c.name+'\n'+c.wave.question);}if(b.dataset.copyContact){const c=getCompany(b.dataset.copyContact);await copyText([c.name,c.contact.phone,c.contact.email,'Назначение: '+c.contact.quality,'Кого запросить: '+c.contact.person,'Источник: '+c.contact.sources,'Контакт не проверялся звонком.'].join('\n'));}if(b.dataset.copyReserve){const r=DATA.reserve.find(r=>r.id===b.dataset.copyReserve);await copyText(r.name+'\nПроверить: '+r.action+'\nПричина: '+r.reason+'\nИсточник: '+r.sources);}if(b.dataset.task){$('#research-task').value=b.dataset.task;buildPrompt();$('#prompt-text').scrollIntoView({behavior:'smooth',block:'center'});toast('Шаблон применён к выбранному объекту.');}if(b.hasAttribute('data-reset'))$('#reset-filters')?.click();});}
async function start(){try{const responses=await Promise.all([fetch('/energy-md/data.json'),fetch('/energy-md/data.ro.json')]);if(responses.some(r=>!r.ok))throw Error('data');const datasets=await Promise.all(responses.map(r=>r.json()));DATASETS={ru:datasets[0],ro:datasets[1]};DATA=DATASETS[UI_LANG];loadSaved();let markup;if(route==='/')markup=home()+universeIntro();else if(route==='/registry')markup=directoryPageHTML('registry');else if(route==='/public-energy')markup=directoryPageHTML('public');else if(route==='/catalog')markup=catalog();else if(route==='/sectors')markup=sectors();else if(route==='/wave')markup=wave();else if(route==='/research')markup=research();else if(route==='/method')markup=method();else if(route==='/sources')markup=sources();else if(route.startsWith('/company/')){const c=getCompany(route.split('/')[2]);if(c)markup=companyPage(c);}else if(route.startsWith('/sector/')){const s=DATA.sectors.find(s=>s.id===route.split('/')[2]);if(s)markup=sectorPage(s);}if(!markup)markup=pageHead('Страница не найдена','Откройте каталог или выберите направление.')+'<div class="content"><a class="button" href="/energy-md/catalog/">Перейти к компаниям ↗</a></div>';$('#main').innerHTML=markup;$$('.site-header nav a').forEach(a=>{const path=localPath(new URL(a.href).pathname).replace(/\/$/,'');if(route===path||(path==='/catalog'&&route.startsWith('/company/'))||(path==='/sectors'&&route.startsWith('/sector/'))){a.classList.add('active');a.setAttribute('aria-current','page');}});if(route==='/catalog')initCatalog();if(route==='/research')initResearch();if(route==='/registry')await initDirectory('registry');if(route==='/public-energy')await initDirectory('public');bindGlobal();window.energyReady?.();document.title='EUGERUS S.A. · '+($('#main h1')?.innerText||'Energy MD').replace(/\s+/g,' ')+' | Energy MD';}catch(error){$('#main').innerHTML='<div class="content" style="padding-top:70px"><h1>Не удалось загрузить данные.</h1><p>Обновите страницу или скачайте исходные документы.</p><a class="button" href="/energy-md/files/Energy-Industry.xlsx">Скачать Excel ↓</a></div>';console.error(error);}}
const dayOrder={factory:0,shift:1,general:2,hypothesis:3,unknown:4,mixed:5};
const dayCandidates=()=>DATA.companies.filter(c=>['factory','shift','general'].includes(c.day.kind)).sort((a,b)=>dayOrder[a.day.kind]-dayOrder[b.day.kind]);
function dayBadge(c){return `<span class="tag ${['factory','shift'].includes(c.day.kind)?'day-strong':''}">${esc(c.day.label)}</span>`;}
function dayPanel(c){return `<section class="panel"><span class="label">ДНЕВНОЙ ПРОФИЛЬ</span><h2>${esc(c.day.label)}</h2>${c.day.hours?`<p class="day-hours">${esc(c.day.hours)}</p>`:''}<p>${esc(c.day.evidence)}</p>${sourceLinks(c.day.sources)}<p class="small-note">${esc(c.day.limitation)}</p><dl class="data-list"><div><dt>Доля дневных кВт·ч из сети</dt><dd>Не установлена</dd></div><div><dt>Расход от 30 000 MDL/мес.</dt><dd>Не подтверждён</dd></div><div><dt>Собственная генерация</dt><dd>${esc(c.generationText||'Требует проверки')}</dd></div></dl><p class="small-note">Не подменять потребление графиком офиса. Считать покупки из сети после собственной генерации.</p></section>${c.registryMatch?`<section class="panel"><span class="label">СОПОСТАВЛЕНИЕ С ASP</span><p><strong>${esc(c.registryMatch.legalName)}</strong></p><p>IDNO ${esc(c.registryMatch.idno)}</p><p>${esc(c.registryMatch.registeredAddress)}</p><p class="small-note">${esc(c.registryMatch.note)}</p>${sourceLinks(c.registryMatch.source)}</section>`:''}`;}
function dayWave(){const strong=dayCandidates().filter(c=>c.day.kind!=='general'),general=dayCandidates().filter(c=>c.day.kind==='general');return pageHead('Дневной приоритет','Начинаем с опубликованных графиков фабрик и производственных смен. Денежный порог и фактическая дневная доля проверяются отдельно.')+`<div class="content"><div class="results-bar"><span>${strong.length} графиков фабрик / смен · ${general.length} общих графиков</span><a class="button secondary small" href="/energy-md/catalog/?day=signal&sort=day">Фильтры и CSV ↓</a></div><h2>Фабрика или производственная смена</h2><div class="company-grid">${strong.map(c=>companyCard(c)).join('')}</div><div class="subsection"><h2>Общий дневной график</h2><p>Это более слабый сигнал: часы приёма и продаж могут отличаться от работы оборудования.</p><div class="company-grid">${general.map(c=>companyCard(c)).join('')}</div></div>${notice()}<details class="panel"><summary>Первоначальная волна из исследования</summary><p>Старые 20 кандидатов сохранены, но не являются дневной рекомендацией. Холод, хлеб и непрерывные процессы требуют отдельной проверки ночной нагрузки.</p><a class="text-link" href="/energy-md/catalog/?wave=1&sort=wave">Открыть первоначальную подборку ↗</a></details></div>`;}
function universeIntro(){return `<section class="section"><div class="section-head"><div><div class="eyebrow">Открытые источники / расширение охвата</div><h2>От десятков карточек<br>к системному поиску</h2></div></div><div class="detail-grid"><article class="panel"><span class="label">ASP · 12.10.2026</span><h3>${num(DATA.registryMeta.count)} записей</h3><p>Юридические лица с заявленной производственной деятельностью. Название, IDNO, регион регистрации и CAEM. Работа предприятия, дневной режим и счёт пока не подтверждены.</p><a class="button secondary" href="/energy-md/registry/">Искать в реестре ↗</a></article><article class="panel"><span class="label">CNED · ЯНВАРЬ–АПРЕЛЬ 2026</span><h3>${num(DATA.publicMeta.largeRows)} строк от 10 000 кВт·ч/мес.</h3><p>Опубликованные месячные объёмы организаций. Строки не равны уникальным организациям. Это физический объём, а не подтверждение 30 000 MDL или дневной доли.</p><a class="button secondary" href="/energy-md/public-energy/">Изучить потребление ↗</a></article></div></section>`;}
let REGISTRY=null, PUBLIC_ENERGY=null, directoryRows=[],directoryPage=0;
const publicGroups={education:'Образование',medical:'Медицина',municipal:'Администрация / муниципальные',other:'Другие организации'};
function directoryPageHTML(type){const reg=type==='registry';return pageHead(reg?'Расширенный реестр ASP':'Опубликованное потребление CNED',reg?'Заявленные виды деятельности помогают найти предприятия для дальнейшего исследования. Реестр не подтверждает работу фабрики, её выручку или расходы.':'Фактические месячные кВт·ч из открытой таблицы. Дневная доля, плательщик по договору и расходы в леях отдельно не установлены.')+`<div class="content"><div class="note-strip">${esc(reg?DATA.registryMeta.note:DATA.publicMeta.note)}</div><div class="filters directory-filters"><div class="field"><label for="directory-q">Название, ${reg?'IDNO, адрес или деятельность':'район или населённый пункт'}</label><input id="directory-q" type="search" placeholder="Например, mobilă, tipar, Bălți…"></div><div class="field"><label for="directory-group">${reg?'Производственное направление':'Тип организации · по названию'}</label><select id="directory-group"><option value="">Все</option>${!reg?Object.entries(publicGroups).map(([k,v])=>`<option value="${k}">${v}</option>`).join(''):''}</select></div><div class="field"><label for="directory-region">${reg?'Регион регистрации':'Район'}</label><select id="directory-region"><option value="">Все</option></select></div>${!reg?'<div class="field"><label for="directory-min">Среднее, от кВт·ч/месяц</label><input id="directory-min" type="number" min="0" value="10000" step="1000"></div>':''}<div class="filter-bottom"><button class="button secondary small" id="directory-export">Выгрузить подборку CSV ↓</button><a href="/energy-md/files/Energy-Day.xlsx" class="text-link" download>Вся база Excel ↓</a></div></div><div class="results-bar"><span id="directory-count" aria-live="polite">Загружаем данные…</span><div class="pagination"><button class="button secondary small" id="directory-prev" aria-label="Предыдущая страница">←</button><span id="directory-page"></span><button class="button secondary small" id="directory-next" aria-label="Следующая страница">→</button></div></div><p class="table-hint">Таблицу можно прокручивать по горизонтали ↔</p><div id="directory-table" class="table-wrap" tabindex="0" role="region" aria-label="Таблица; прокрутите по горизонтали"></div><div class="note-strip">${reg?'Адрес здесь — регистрационный. Один вид деятельности может быть дополнительным. Пустая дата ликвидации не означает, что производство действует.':'Среднее рассчитано по заполненным месяцам января–апреля 2026, включая нулевые значения. Пустое значение не заменяется нулём. Строки с одинаковым названием не сложены. Отбор по 10 000 кВт·ч — исследовательский фильтр, не эквивалент денежного порога.'}</div><p>${sourceLinks(reg?DATA.registryMeta.source:DATA.publicMeta.source)}</p></div>`;}
async function initDirectory(type){const reg=type==='registry';try{const res=await fetch(reg?'/energy-md/registry.json':'/energy-md/public-energy.json');if(!res.ok)throw Error('fetch');const data=await res.json();if(reg)REGISTRY=data;else PUBLIC_ENERGY=data;const regions=[...new Set(data.rows.map(r=>reg?r[3]:r.district))].filter(Boolean).sort((a,b)=>a.localeCompare(b,'ro'));$('#directory-region').innerHTML='<option value="">Все</option>'+regions.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');if(reg)$('#directory-group').innerHTML='<option value="">Все виды деятельности</option>'+data.activities.map((a,i)=>`<option value="${i}">CAEM ${esc(a.code)} · rev.${a.version} · ${esc(a.description)}</option>`).join('');for(const id of ['directory-q','directory-group','directory-region',...(!reg?['directory-min']:[])])$('#'+id).addEventListener(id==='directory-q'||id==='directory-min'?'input':'change',()=>{directoryPage=0;filterDirectory(type);});$('#directory-prev').addEventListener('click',()=>{directoryPage--;renderDirectory(type);});$('#directory-next').addEventListener('click',()=>{directoryPage++;renderDirectory(type);});$('#directory-export').addEventListener('click',()=>exportDirectory(type));filterDirectory(type);}catch{$('#directory-count').textContent='Не удалось загрузить таблицу. Обновите страницу или скачайте Excel.';}}
function directoryFilter(type,q='',group='',region='',minimum=0){q=searchKey(q.trim());if(type==='registry')return REGISTRY.rows.filter(r=>(!group||r[4].includes(Number(group)))&&(!region||r[3]===region)&&(!q||searchKey([r[0],r[1],r[2],...r[4].map(i=>REGISTRY.activities[i].description)].join(' ')).includes(q)));return PUBLIC_ENERGY.rows.filter(r=>(!group||r.group===group)&&(!region||r.district===region)&&r.average>=minimum&&(!q||searchKey([r.name,r.district,r.locality].join(' ')).includes(q))).sort((a,b)=>b.average-a.average);}
function filterDirectory(type){directoryRows=directoryFilter(type,$('#directory-q').value,$('#directory-group').value,$('#directory-region').value,Math.max(0,Number($('#directory-min')?.value)||0));renderDirectory(type);}
function renderDirectory(type){const reg=type==='registry';const pages=Math.max(1,Math.ceil(directoryRows.length/30));directoryPage=Math.max(0,Math.min(directoryPage,pages-1));$('#directory-prev').disabled=directoryPage===0;$('#directory-next').disabled=directoryPage>=pages-1;$('#directory-export').disabled=!directoryRows.length;$('#directory-page').textContent=`${directoryPage+1} / ${pages}`;$('#directory-count').textContent=`${num(directoryRows.length)} строк · ${reg?'статус производства не проверен':'кВт·ч; не сумма платежа'}`;const heads=reg?['ЮРЛИЦО / IDNO','АДРЕС РЕГИСТРАЦИИ','ЗАЯВЛЕННОЕ ПРОИЗВОДСТВО','ДАЛЬШЕ']:['ОРГАНИЗАЦИЯ / СТРОКА XLSX','РАЙОН','ЯНВ','ФЕВ','МАР','АПР','СРЕДНЕЕ','ОГРАНИЧЕНИЯ'];const body=directoryRows.slice(directoryPage*30,directoryPage*30+30).map(r=>reg?`<tr><td><strong>${esc(r[1])}</strong><br>${r[0]}</td><td>${esc(r[2])}</td><td>${r[4].map(i=>{const a=REGISTRY.activities[i];return esc(a.code+' (rev.'+a.version+') '+a.description);}).join('<br>')}</td><td><a class="text-link" target="_blank" rel="noopener noreferrer" href="https://www.google.com/search?q=${encodeURIComponent(r[0]+' '+r[1]+' producere fabrica program de lucru contacte')}">Проверить ↗</a><br><button class="copy-small" data-directory-copy="${r[0]}">Копировать задачу</button></td></tr>`:`<tr><td><strong>${esc(r.name)}</strong><br>Лист 2026 · строка ${r.sourceRow}</td><td>${esc(r.district)}<br>${esc(r.locality)}</td>${r.months.map(v=>`<td>${v==null?'—':num(v)}</td>`).join('')}<td><strong>${num(r.average)}</strong></td><td>${esc(publicGroups[r.group])}<br>${r.duplicateName?'Название повторяется. ':''}${r.group==='municipal'?'Может включать ночное освещение.':r.group==='education'?'Возможны общежития и ночной фон.':'Дневной профиль не установлен.'}</td></tr>`).join('');$('#directory-table').innerHTML=`<table class="financial-table directory-table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${heads.length}">Совпадений нет. Измените условия.</td></tr>`}</tbody></table>`;$$('[data-directory-copy]').forEach(b=>b.addEventListener('click',()=>{const r=REGISTRY.rows.find(r=>r[0]===b.dataset.directoryCopy);copyText(`Проверь предприятие ${r[1]}, IDNO ${r[0]}, Республика Молдова. Источник выявления: ASP от 12.10.2026, ${REGISTRY.source}. Установи, действует ли производство, адрес цеха, оборудование, выручку с годом и источником, публичный деловой контакт, производственные смены, ночной фон и собственную генерацию. Основной приоритет — преимущественно дневные покупки электроэнергии из сети от 30 000 MDL в месяц. Регистрационный адрес ${r[2]} не считать автоматически адресом фабрики. Ищи опубликованные счета, отчёты, закупки и интервальные кВт·ч; не выдумывай банковские платежи. Раздели факт, вывод и неизвестное; дай ссылки и даты. Сообщения компании не отправляй.`);}));}
function downloadCSV(rows,name){const cell=v=>{let s=String(v??'');if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),5000);}
function exportDirectory(type){if(type==='registry')downloadCSV([['IDNO','Юрлицо','Адрес регистрации','Регион','Производственные виды','Состояние','Источник'],...directoryRows.map(r=>[r[0],r[1],r[2],r[3],r[4].map(i=>{const a=REGISTRY.activities[i];return a.code+' rev.'+a.version+' '+a.description;}).join('; '),'Деятельность заявлена; работа, дневной профиль и расходы не проверены',REGISTRY.source])],'Energy-ASP-selection.csv');else downloadCSV([['Строка XLSX 2026','Организация','Район','Населённый пункт','Янв кВт·ч','Фев кВт·ч','Мар кВт·ч','Апр кВт·ч','Среднее кВт·ч','Заполненных месяцев','Название повторяется','Источник','Ограничение'],...directoryRows.map(r=>[r.sourceRow,r.name,r.district,r.locality,...r.months,r.average,r.reportedMonths,r.duplicateName?'Да':'Нет',PUBLIC_ENERGY.source,'Дневной профиль и расходы MDL неизвестны; строки не суммировать'])],'Energy-CNED-selection.csv');}

start();
